import { MakeLogicType, kea, key, path, props, selectors } from 'kea'
import { router } from 'kea-router'

import { parseIntervalParam } from 'lib/utils/timeBuckets'
import { urls } from 'scenes/urls'

import { Breadcrumb } from '~/types'

import type { MCPAnalyticsToolDetailLogicProps } from './mcpAnalyticsToolDetailLogic'
import { mcpToolQualityUrlWithDates } from './mcpAnalyticsToolQualityLogic'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface mcpToolDetailSceneLogicValues {
    breadcrumbs: Breadcrumb[]
    toolName: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface mcpToolDetailSceneLogicMeta {
    key: string
    __keaTypeGenInternalSelectorTypes: {
        toolName: (toolName: string) => string
        breadcrumbs: (toolName: string, searchParams: Record<string, any>) => Breadcrumb[]
    }
}

export type mcpToolDetailSceneLogicType = MakeLogicType<
    mcpToolDetailSceneLogicValues,
    {},
    MCPAnalyticsToolDetailLogicProps,
    mcpToolDetailSceneLogicMeta
>

// The tool page's scene logic. It loads no data, so the redesign and the legacy UI can each bind their own.
export const mcpToolDetailSceneLogic = kea<mcpToolDetailSceneLogicType>([
    path(['products', 'mcp_analytics', 'frontend', 'mcpToolDetailSceneLogic']),
    props({} as MCPAnalyticsToolDetailLogicProps),
    key((props) => props.toolName),
    selectors({
        toolName: [(_, p) => [p.toolName], (toolName: string): string => toolName],
        breadcrumbs: [
            (s) => [s.toolName, router.selectors.searchParams],
            (toolName: string, searchParams: Record<string, any>): Breadcrumb[] => [
                { key: 'mcp-analytics', name: 'MCP analytics', path: urls.mcpAnalytics(), iconType: 'mcp_analytics' },
                {
                    key: 'mcp-analytics-tool-quality',
                    name: 'Tool quality',
                    path: mcpToolQualityUrlWithDates(
                        {
                            dateFrom: typeof searchParams.date_from === 'string' ? searchParams.date_from : null,
                            dateTo: typeof searchParams.date_to === 'string' ? searchParams.date_to : null,
                        },
                        parseIntervalParam(searchParams.interval)
                    ),
                },
                { key: 'mcp-analytics-tool', name: toolName },
            ],
        ],
    }),
])
